	function ledger_till_date_result_today_admin($params)
	{
		$this->db->trans_start();

		$ledger_id = $params['ledger_id'];
		$date = date('Y-m-d', strtotime($params['date']));
		$first_day_this_month = date('Y-m-01');
		$user_id = $this->session->userdata['id'];

		// SQL for today's data
		$sql = "
			SELECT 
				tl.ledger_name, 
				tl.hissa AS pattiperc, 
				tl.openingbalance AS openingbalance, 
				tl.hissa_select AS hissa_select, 
				tl.dara_rate AS ledgerdara_rate, 
				tl.dara_commision AS ledgerdara_commision, 
				tl.akhar_rate AS ledgerakhar_rate, 
				tl.akhar_commission AS ledgerakhar_commission, 
				topen.number AS number,
				topen.date AS opendate, 
				ts.shift_name, 
				ust.shift_id,
				tdsp.*, 
				tdsp.Open_Number_amount AS oamnt, 
				tdsp.Akhar_Number_amount AS akmnt, 
				tdsp.Total_Number_amount AS tamnt 
			FROM 
				Tb_Date_shift_party_entry AS tdsp
			JOIN  
				user_shift_timings AS ust ON ust.id = tdsp.shiftid 
			JOIN 
				tbl_shift AS ts ON ts.id = ust.shift_id
			LEFT JOIN 
				tbl_openno AS topen ON topen.shift_id = ts.id
				AND topen.date = tdsp.Date
			JOIN 
				tbl_ledger AS tl ON tl.id = tdsp.PartyId 
			WHERE 
				tdsp.PartyId = ? 
				AND tdsp.Date = ? 
				AND tl.updated_by = ?
			GROUP BY 
				tdsp.id, tl.id, tdsp.Date;
		";

		$query = $this->db->query($sql, array($ledger_id, $date, $user_id));
		$data['today'] = $query->result_array();

		// SQL for before today's data
		$sqlold = "
			SELECT 
				tl.ledger_name,
				tl.hissa AS pattiperc,
				tl.openingbalance AS openingbalance,
				tl.hissa_select AS hissa_select,
				tl.dara_rate AS ledgerdara_rate,
				tl.dara_commision AS ledgerdara_commision,
				tl.akhar_rate AS ledgerakhar_rate,
				tl.akhar_commission AS ledgerakhar_commission,
				topen.number,
				topen.date AS opendate,
				ts.shift_name, 
				tdsp.*, 
				tdsp.Open_Number_amount AS oamnt, 
				tdsp.Akhar_Number_amount AS akmnt,
				tdsp.Total_Number_amount AS tamnt 
			FROM 
				Tb_Date_shift_party_entry AS tdsp
			JOIN  
				user_shift_timings AS ust ON ust.id = tdsp.shiftid
			JOIN 
				tbl_shift AS ts ON ts.id = ust.shift_id
			LEFT JOIN 
				tbl_openno AS topen ON topen.date = tdsp.Date
			JOIN 
				tbl_ledger AS tl ON tl.id = tdsp.PartyId
			WHERE 
				tdsp.PartyId = ? 
				AND tl.updated_by = ? 
		";

		// Check if the date is the first day of the month
		if (strtotime($first_day_this_month) == strtotime($date)) {
			$sqlold .= "AND tdsp.Date = ? 
						GROUP BY tdsp.id";
			$data['before'] = [];
		} else {
			$sqlold .= "AND tdsp.Date < ? 
						AND tdsp.Date >= ? 
						GROUP BY tdsp.id";
			$data['before'] = $this->db->query($sqlold, array($ledger_id, $user_id, $date, $first_day_this_month))->result_array();
		}

		$this->db->trans_complete();

		return $data;
		// return $query->result_array(); 
	}
	function ledger_till_date_result_today($params)
	{
		// Convert the input date to Y-m-d format (if it's not already)
		$formatted_date = date('Y-m-d', strtotime($params['date']));

		// Prepare the query for today's result
		$sql = "SELECT 
        tl.ledger_name, 
        tl.hissa AS pattiperc, 
        tl.openingbalance AS openingbalance, 
        tl.hissa_select AS hissa_select, 
        tl.dara_rate AS ledgerdara_rate, 
        tl.dara_commision AS ledgerdara_commision, 
        tl.akhar_rate AS ledgerakhar_rate, 
        tl.akhar_commission AS ledgerakhar_commission, 
        topen.number AS number,
        topen.date AS opendate, 
        ts.shift_name, 
        ust.shift_id,
        tdsp.*, 
        (tdsp.Open_Number_amount) AS oamnt, 
        (tdsp.Akhar_Number_amount) AS akmnt, 
        (tdsp.Total_Number_amount) AS tamnt 
    FROM 
        Tb_Date_shift_party_entry AS tdsp
    JOIN  
        user_shift_timings AS ust ON ust.id = tdsp.shiftid 
    JOIN 
        tbl_shift AS ts ON ts.id = ust.shift_id
    LEFT JOIN 
        tbl_openno AS topen ON topen.shift_id = ust.id 
        AND STR_TO_DATE(topen.date, '%d-%m-%Y') = tdsp.Date
    JOIN 
        tbl_ledger AS tl ON tl.id = tdsp.PartyId 
    WHERE 
        tdsp.PartyId = '" . $params['ledger_id'] . "' 
        AND tdsp.Date = '" . $formatted_date . "'
        AND tdsp.status = 1
        AND topen.updated_by != 1
		AND STR_TO_DATE(topen.date, '%d-%m-%Y') IS NOT NULL
    GROUP BY 
        ts.id, tl.id, ust.shift_id, topen.number, tdsp.Date;";

		// Print today's query for debugging
		//  echo "Today's SQL Query: <br>" . $sql . "<br><br>";

		// Execute the query for today's data
		$query = $this->db->query($sql);
		$data['today'] = $query->result_array();

		// First day of this month
		$first_day_this_month = date('Y-m-01');

		// Prepare the query for previous data (before today)
		$sqlold = "SELECT 
        tl.ledger_name,
        tl.hissa AS pattiperc,
        tl.openingbalance AS openingbalance,
        tl.hissa_select AS hissa_select,
        tl.dara_rate AS ledgerdara_rate,
        tl.dara_commision AS ledgerdara_commision,
        tl.akhar_rate AS ledgerakhar_rate,
        tl.akhar_commission AS ledgerakhar_commission,
        topen.number,
        topen.date AS opendate,
        ts.shift_name, 
        tdsp.*, 
        (tdsp.Open_Number_amount) AS oamnt, 
        (tdsp.Akhar_Number_amount) AS akmnt,
        (tdsp.Total_Number_amount) AS tamnt
    FROM 
        Tb_Date_shift_party_entry AS tdsp
    JOIN 
        user_shift_timings AS ust ON ust.id = tdsp.shiftid
    JOIN 
        tbl_shift AS ts ON ts.id = ust.shift_id
    JOIN 
        tbl_openno AS topen ON  STR_TO_DATE(topen.date, '%d-%m-%Y') = tdsp.Date
    JOIN 
        tbl_ledger AS tl ON tl.id = tdsp.PartyId
    WHERE 
        tdsp.status = 1
        AND tdsp.PartyId = '" . $params['ledger_id'] . "'";

		// If the date is the first day of the month, only get today's data
		if (strtotime($first_day_this_month) == strtotime($formatted_date)) {
			$sqlold .= " AND tdsp.Date = '" . $formatted_date . "'
        GROUP BY tdsp.id";
			$data['before'] = array();  // No previous data if it's the first day
		} else {
			$sqlold .= " AND tdsp.Date < '" . $formatted_date . "'
        AND tdsp.Date >= '" . $first_day_this_month . "'
        GROUP BY tdsp.id";

			// Print previous data query for debugging
			// echo "Previous Data SQL Query: <br>" . $sqlold . "<br><br>";

			// Execute the query for previous data
			$query = $this->db->query($sqlold);
			$data['before'] = $query->result_array();
		}

		// Return the data
		return $data;
	}


