	function ledger_today_admin($params)
	{
		$this->db->trans_start();

		$ledger_id = $params['ledger_id'];
		$date = date('Y-m-d', strtotime($params['date'])); // Today's date
		$user_id = $this->session->userdata['id'];

		$sql = "
        SELECT 
            tl.ledger_name, 
            tl.hissa AS pattiperc, 
            tl.openingbalance AS openingbalance, 
            tl.hissa_select AS hissa_select, 
            tl.dara_rate AS ledgerdara_rate, 
            tl.dara_commision AS ledgerdara_commision, 
            tl.akhar_rate AS ledgerakhar_rate, 
            tl.akhar_commission AS ledgerakhar_commission, 
            topen.number AS number,
            topen.date AS opendate, 
            ts.shift_name, 
            ust.shift_id,
            tdsp.*, 
            tdsp.Open_Number_amount AS oamnt, 
            tdsp.Akhar_Number_amount AS akmnt, 
            tdsp.Total_Number_amount AS tamnt 
        FROM 
            Tb_Date_shift_party_entry AS tdsp
        JOIN  
            user_shift_timings AS ust ON ust.id = tdsp.shiftid 
        JOIN 
            tbl_shift AS ts ON ts.id = ust.shift_id
        LEFT JOIN 
            tbl_openno AS topen ON topen.shift_id = ts.id
            AND topen.date = tdsp.Date
        JOIN 
            tbl_ledger AS tl ON tl.id = tdsp.PartyId 
        WHERE 
            tdsp.PartyId = ? 
            AND tdsp.Date = ? 
            AND tl.updated_by = ?
        GROUP BY 
            tdsp.id, tl.id, tdsp.Date;
    ";

		$query = $this->db->query($sql, array($ledger_id, $date, $user_id));
		$data['today'] = $query->result_array();

		$this->db->trans_complete();

		return $data;
	}
