		$openingbal = $this->getopeningbaltoday($pid);
		$arr = 0;
		$tamount = 0;
		$ta = 0;
		$tb = 0;
		$arr = $arr + ((!empty($vcamnt)) ? $vcamnt[0]['Amount'] : 0);
		$arr = $arr - ((!empty($vccrdtby)) ? $vccrdtby[0]['Amount'] : 0);
