	function get_all_tbl_openno_admin_dashboard()
	{
		$admin_id = $this->session->userdata['id'];

		// Step 1: Fetch latest dates for each shift using subquery
		$this->db->select('shift_id, MAX(DATE(created_at)) AS latest_date');
		$this->db->from('tbl_openno');
		$this->db->where('updated_by', $admin_id);
		$this->db->group_by('shift_id');
		$subquery = $this->db->get_compiled_select();

		// Step 2: Now, fetch main data and join with subquery result
		$this->db->select('tbl_openno.*, tbl_shift.shift_name');
		$this->db->from('tbl_openno');

		// Join with user_shift_timings based on admin role
		if ($admin_id == 1) {
			$this->db->join('user_shift_timings', 'user_shift_timings.shift_id = tbl_openno.shift_id');
		} else {
			$this->db->join('user_shift_timings', 'user_shift_timings.id = tbl_openno.shift_id');
		}

		// Join with tbl_shift
		$this->db->join('tbl_shift', 'tbl_shift.id = user_shift_timings.shift_id');

		// Join with the subquery using shift_id and latest date
		$this->db->join(
			"($subquery) AS latest_dates",
			"latest_dates.shift_id = tbl_openno.shift_id AND DATE(tbl_openno.created_at) = latest_dates.latest_date",
			'inner'
		);

		// Filter by current admin
		$this->db->where('tbl_openno.updated_by', $admin_id);

		// Order by ID in descending order
		$this->db->order_by('tbl_openno.id', 'DESC');

		// Execute the query
		$query = $this->db->get();
		return $query->result_array();
	}

